window.GENERATIONS = [{"number":1,"name":"Primera generación","years":"1972–1980","summary":"La era de las consolas dedicadas. Juegos integrados en el hardware (variantes de Pong) sin cartuchos intercambiables. Magnavox Odyssey abre el mercado doméstico."},{"number":2,"name":"Segunda generación","years":"1976–1992","summary":"Llegan los cartuchos intercambiables y las CPU programables. Atari 2600 domina hasta el crash del videojuego de 1983 en Norteamérica."},{"number":3,"name":"Tercera generación (8 bits)","years":"1983–2003","summary":"El renacimiento tras el crash, liderado por la NES/Famicom de Nintendo y la Master System de Sega. Se consolidan las franquicias modernas."},{"number":4,"name":"Cuarta generación (16 bits)","years":"1987–2004","summary":"La guerra de los 16 bits entre Super Nintendo y Mega Drive/Genesis. Audio y gráficos de calidad arcade en el salón."},{"number":5,"name":"Quinta generación (32/64 bits)","years":"1993–2006","summary":"El salto a las 3D poligonales y al CD-ROM. PlayStation irrumpe y redefine la industria frente a Saturn y Nintendo 64."},{"number":6,"name":"Sexta generación","years":"1998–2013","summary":"El DVD como soporte, el juego online se populariza y Microsoft entra con Xbox. Dreamcast, PS2, GameCube y Xbox."},{"number":7,"name":"Séptima generación (HD)","years":"2005–2017","summary":"Alta definición, logros/trofeos, tiendas digitales y controles por movimiento. Wii, Xbox 360 y PlayStation 3."},{"number":8,"name":"Octava generación","years":"2012–presente","summary":"Arquitecturas tipo PC x86, juego en la nube incipiente y la híbrida Switch. PS4, Xbox One, Wii U y Nintendo Switch."},{"number":9,"name":"Novena generación","years":"2020–presente","summary":"SSD ultrarrápidos, ray tracing, 4K/120 Hz y retrocompatibilidad. PlayStation 5 y Xbox Series X|S."}];
